+                        FILE_NAMES_PROPERTY_NAME));
+            }
+            return constructorStrategy;
+        }
+        if (configured == null || "random".equals(configured)) {
+            return description -> UUID.randomUUID().toString();
+        }
+        if ("description".equals(configured)) {
+            return new DescriptionRuleViolationFileNameStrategy();
+        }
+        try {
+            Class<?> strategyType = Class.forName(configured);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyType)) {
+                throw new Exception("does not implement " + RuleViolationFileNameStrategy.class.getName());
+            }
+            Constructor<?> constructor = strategyType.getDeclaredConstructor();
+            if (!Modifier.isPublic(strategyType.getModifiers()) || !Modifier.isPublic(constructor.getModifiers())) {
+                throw new Exception("must have a public no-argument constructor");
+            }
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (Exception e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate %s configured by %s=%s",
+                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, configured), e);
+        }
+    }
+
+    private Integrity integrityFrom(String configured) {
+        for (Integrity value : Integrity.values()) {
+            if (value.value.equals(configured)) {
+                return value;
+            }
+        }
