+    private IntegrityResult inspect(Path folderPath, Path rulesPath, Properties properties,
+            RuleViolationFileNameStrategy strategy, Integrity configuredIntegrity) {
+        IntegrityResult result = new IntegrityResult();
+        List<Entry> entries = new ArrayList<>();
+        Map<String, Integer> names = new HashMap<>();
+        Map<Path, Integer> resolvedFiles = new HashMap<>();
+        for (String description : properties.stringPropertyNames()) {
+            String name = properties.getProperty(description);
+            Entry entry = new Entry(description, name);
+            if (configuredIntegrity != Integrity.IGNORE) {
+                entry.derivedName = deriveName(strategy, description);
+            }
+            entry.currentPath = pathFor(folderPath, name);
+            entry.derivedPath = pathFor(folderPath, entry.derivedName);
+            entries.add(entry);
+            names.put(name, names.containsKey(name) ? names.get(name) + 1 : 1);
+        }
+
+        for (Entry entry : entries) {
+            entry.shared = names.get(entry.name) > 1;
+            entry.regularFile = isRegularFileDirectlyInFolder(entry.currentPath, folderPath);
+            if (entry.regularFile) {
+                try {
+                    entry.resolvedFile = entry.currentPath.toRealPath();
+                    resolvedFiles.put(entry.resolvedFile,
+                            resolvedFiles.containsKey(entry.resolvedFile) ? resolvedFiles.get(entry.resolvedFile) + 1 : 1);
+                } catch (IOException e) {
+                    throw new StoreInitializationFailedException(e);
+                }
+            }
+            entry.broken = !entry.regularFile;
+            if (!entry.broken) {
+                entry.resolved = hasNoViolations(entry.currentPath);
+            }
+            entry.misplaced = !Objects.equals(entry.name, entry.derivedName);
+        }
+        for (Entry entry : entries) {
+            if (entry.resolvedFile != null && resolvedFiles.get(entry.resolvedFile) > 1) {
+                entry.shared = true;
+            }
+            int derivedUsers = 0;
+            for (Entry candidate : entries) {
+                if (Objects.equals(entry.derivedName, candidate.derivedName)) {
+                    derivedUsers++;
+                }
+            }
+            entry.colliding = derivedUsers > 1;
+            if (entry.misplaced) {
+                boolean derivedIsRecorded = names.containsKey(entry.derivedName);
+                boolean derivedExists = entry.derivedPath != null
+                        && Files.exists(entry.derivedPath, LinkOption.NOFOLLOW_LINKS);
+                boolean escapes = !isDirectlyInFolder(entry.derivedPath, folderPath);
+                entry.occupied = derivedIsRecorded || derivedExists || escapes
+                        || samePath(entry.derivedPath, rulesPath);
+            }
+        }
