+    private String deriveName(RuleViolationFileNameStrategy strategy, String description) {
+        String result = strategy.createRuleFileName(description);
+        if (result == null || result.isEmpty()) {
+            throw new StoreInitializationFailedException(String.format(
+                    "RuleViolationFileNameStrategy returned no name for rule '%s'", description));
+        }
+        return result;
+    }
+
+    private boolean hasNoViolations(Path file) {
+        try {
+            String contents = new String(Files.readAllBytes(file), UTF_8);
+            return ONLY_LINE_BREAKS_PATTERN.matcher(contents).matches();
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private List<String> unownedFiles(Path folderPath, Path rulesPath, Properties properties) {
+        Set<String> recordedNames = new HashSet<>(properties.stringPropertyNames().stream().map(this::normalizePropertyValue).collect(toList()));
+        List<String> result = new ArrayList<>();
+        try (DirectoryStream<Path> files = Files.newDirectoryStream(folderPath)) {
+            for (Path file : files) {
+                if (samePath(file, rulesPath)) {
+                    continue;
+                }
+                if (Files.isRegularFile(file) && !recordedNames.contains(file.getFileName().toString())) {
+                    result.add(file.getFileName().toString());
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        Collections.sort(result);
+        return result;
+    }
+
+    private String normalizePropertyValue(String value) {
+        return ensureUnixLineBreaks(value);
+    }
+
+    private void repair(IntegrityResult result, Properties properties, Path folderPath, Path rulesPath) {
+        boolean changed = false;
+        for (Entry entry : result.entries) {
+            // Shared entries are deliberately left untouched, including when they are also broken,
+            // resolved, misplaced, colliding, or occupied.
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                properties.remove(entry.description);
+                changed = true;
+            } else if (entry.resolved) {
+                if (samePath(entry.currentPath, rulesPath)) {
+                    continue;
+                }
+                deleteResolvedFile(entry.currentPath);
+                properties.remove(entry.description);
+                changed = true;
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied
+                    && !samePath(entry.currentPath, rulesPath)) {
+                moveEntryFile(entry.currentPath, entry.derivedPath);
+                properties.setProperty(ensureUnixLineBreaks(entry.description), ensureUnixLineBreaks(entry.derivedName));
+                changed = true;
+            }
+        }
+        if (changed) {
+            // The index is written once, after all file changes, and never for an inspection
+            // that found only shared or unowned files.
+            ((StoreState) currentStateFor(folderPath, rulesPath)).sync();
+        }
+    }
+
+    private StoreState currentStateFor(Path folderPath, Path rulesPath) {
+        try {
+            return STORES_BY_PATH.get(rulesPath.toFile().getCanonicalPath());
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void moveEntryFile(Path source, Path destination) {
+        if (!isDirectlyInFolder(destination, storeFolderPathFor(source))) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot repair entry to a path outside the store folder: %s", destination));
+        }
+        try {
+            Path actualSource = Files.isSymbolicLink(source) ? source.toRealPath() : source;
+            Files.move(actualSource, destination);
+            if (!actualSource.equals(source)) {
+                Files.delete(source);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private Path storeFolderPathFor(Path source) {
+        // During initialization storeFolderPath is not assigned until the inspection succeeds.
+        return storeFolderPath != null ? storeFolderPath : source.toAbsolutePath().normalize().getParent();
+    }
+
+    private void deleteResolvedFile(Path file) {
+        try {
+            if (!Files.exists(file, LinkOption.NOFOLLOW_LINKS)) {
+                return;
+            }
+            if (Files.isSymbolicLink(file)) {
+                Path target = file.toRealPath();
+                Files.delete(target);
+                Files.delete(file);
+            } else {
+                Files.delete(file);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private boolean isRegularFileDirectlyInFolder(Path path, Path folderPath) {
+        return isDirectlyInFolder(path, folderPath) && Files.isRegularFile(path);
+    }
+
+    private boolean isDirectlyInFolder(Path path, Path folderPath) {
+        return path != null && folderPath != null && folderPath.equals(path.getParent());
+    }
+
+    private Path pathFor(Path folderPath, String name) {
+        if (name == null) {
+            return null;
+        }
+        try {
+            return folderPath.resolve(name).normalize();
+        } catch (RuntimeException e) {
+            return null;
+        }
+    }
+
+    private boolean samePath(Path first, Path second) {
+        return first != null && second != null && first.toAbsolutePath().normalize().equals(second.toAbsolutePath().normalize());
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        storeState.lock.readLock().lock();
+        try {
+            return storeState.properties.containsKey(ensureUnixLineBreaks(rule.getDescription()));
+        } finally {
+            storeState.lock.readLock().unlock();
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+        storeState.lock.writeLock().lock();
+        try {
+            String description = ensureUnixLineBreaks(rule.getDescription());
+            String existingFileName = storeState.properties.getProperty(description);
+            if (violations.isEmpty() && integrity == Integrity.REPAIR) {
+                forgetKnownRuleOnRepair(description, existingFileName);
+                return;
+            }
+            if (existingFileName == null && violations.isEmpty()) {
+                return;
+            }
+
+            String fileName = existingFileName != null ? existingFileName : deriveName(ruleViolationFileNameStrategy, description);
+            Path destination = pathFor(storeFolderPath, fileName);
+            validateSaveDestination(destination, fileName, existingFileName != null);
+            writeAtomically(violations, destination);
+            if (existingFileName == null) {
+                storeState.properties.setProperty(description, ensureUnixLineBreaks(fileName));
+                try {
+                    storeState.sync();
+                } catch (RuntimeException e) {
+                    storeState.properties.remove(description);
+                    deleteQuietly(destination);
+                    throw e;
+                }
+            }
+        } finally {
+            storeState.lock.writeLock().unlock();
+        }
+    }
+
+    private void forgetKnownRuleOnRepair(String description, String fileName) {
+        if (fileName == null) {
+            return;
+        }
+        if (!isSharedWithAnotherEntry(description, fileName)) {
+            Path file = pathFor(storeFolderPath, fileName);
+            if (file != null && Files.exists(file, LinkOption.NOFOLLOW_LINKS)) {
+                if (!isDirectlyInFolder(file, storeFolderPath) || samePath(file, storedRulesPath)
+                        || (!Files.isRegularFile(file) && !Files.isSymbolicLink(file))) {
+                    throw new StoreUpdateFailedException(String.format(
+                            "Cannot remove violation file for rule '%s'", description));
+                }
+                try {
+                    deleteResolvedFile(file);
+                } catch (StoreInitializationFailedException e) {
+                    throw new StoreUpdateFailedException(e);
+                }
+            }
+        }
+        storeState.properties.remove(description);
+        storeState.sync();
+    }
+
+    private boolean isSharedWithAnotherEntry(String description, String fileName) {
+        Path file = pathFor(storeFolderPath, fileName);
+        Path real = null;
+        if (file != null && Files.isRegularFile(file)) {
+            try {
+                real = file.toRealPath();
+            } catch (IOException ignored) {
+                // It will be treated as an unshared, removable file below.
+            }
+        }
+        for (String otherDescription : storeState.properties.stringPropertyNames()) {
+            if (description.equals(otherDescription)) {
+                continue;
+            }
+            String otherName = storeState.properties.getProperty(otherDescription);
+            if (Objects.equals(fileName, otherName)) {
+                return true;
+            }
+            Path other = pathFor(storeFolderPath, otherName);
+            if (real != null && other != null && Files.isRegularFile(other)) {
+                try {
+                    if (real.equals(other.toRealPath())) {
+                        return true;
+                    }
+                } catch (IOException ignored) {
+                    // The other entry cannot share a file that no longer resolves.
+                }
+            }
+        }
+        return false;
+    }
