+    private void validateSaveDestination(Path destination, String fileName, boolean existingEntry) {
+        if (destination == null || !isDirectlyInFolder(destination, storeFolderPath)
+                || samePath(destination, storedRulesPath)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Refusing to write violation file '%s' outside the store's data files", fileName));
+        }
+        if (!existingEntry) {
+            if (Files.exists(destination, LinkOption.NOFOLLOW_LINKS)
+                    || storeState.properties.stringPropertyNames().stream()
+                    .map(storeState.properties::getProperty)
+                    .anyMatch(fileName::equals)) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Refusing to overwrite an existing or recorded violation file '%s'", fileName));
+            }
+        } else if (Files.exists(destination, LinkOption.NOFOLLOW_LINKS)
+                && Files.isDirectory(destination, LinkOption.NOFOLLOW_LINKS)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Refusing to overwrite directory '%s'", fileName));
+        }
